3	//! Postgres-backed `AuditLog` (SeaORM). `record_out_of_band` is a single autocommit insert
4	//! (no txn — the port doc contract: the audit write happens after the triggering
5	//! transaction already committed, or after a denial, so it is never part of that
6	//! transaction's atomicity). `record` (SMA-446, Slice B) is its in-txn twin: it recovers the
7	//! caller's SeaORM transaction via `uow::recover_txn` (B3) and inserts the SAME
8	//! `entry_to_model`-built row on it, so the audit row only becomes visible if the caller's own
9	//! transaction commits — used when the audit write must be atomic with the mutation it
10	//! describes (and typically the same mutation's `Outbox::enqueue`, `pg_outbox.rs`). `query`
11	//! builds a keyset-paginated read: `ORDER BY id DESC` (UUIDv7 ids, so this doubles as
12	//! occurred-at-descending) with `WHERE id < cursor` for the next page, an equality filter per
13	//! present `AuditFilter` field, and `LIMIT filter.capped_limit()`.
14	//!
15	//! `determining_policies`/`detail` are TEXT columns (m0006, no native `text[]`/`jsonb` —
16	//! mirrors `entities::audit_log`'s doc and `pg_api_keys.rs::roles_to_column`'s precedent):
17	//! `determining_policies` is always stored as a JSON-encoded `Vec<String>` (never `NULL` —
18	//! simplest of the two options the column supports); `detail` is the `serde_json::Value`'s
19	//! plain `to_string()`. Both serializations are infallible (`Vec<String>`/`Value` always
20	//! serialize); only the READ side can fail, when a stored value doesn't parse back — a
21	//! data-integrity break surfaced as `RepositoryError::Backend`, never a silent default,
22	//! mirroring `pg_repository.rs::map_principal_row`'s posture for a bad enum.
23	
24	use super::entities::audit_log;
25	use super::map_err;
26	use super::uow::recover_txn;
27	use async_trait::async_trait;
28	use metrics::counter;
29	use paigasus_iam_core::{AuditEntry, AuditFilter, AuditLog, AuditOutcome, RepositoryError, Transaction};
30	use paigasus_observability::names;
31	use sea_orm::{ActiveModelTrait, ColumnTrait, DatabaseConnection, EntityTrait, QueryFilter, QueryOrder, QuerySelect, Set};
32	
33	// `Clone` lets the composition root hold a sink handle inside a `#[derive(Clone)]` service
34	// (mirrors `PgPrincipalRepository`'s precedent) — cheap: `DatabaseConnection` clones an
35	// `Arc`-backed pool handle, not a connection.
36	#[derive(Clone)]
37	pub struct PgAuditLog {
38	    db: DatabaseConnection,
39	}
40	
41	impl PgAuditLog {
42	    #[must_use]
43	    pub fn new(db: DatabaseConnection) -> Self {
44	        PgAuditLog { db }
45	    }
46	}
47	
48	fn backend_err(msg: impl std::fmt::Display) -> RepositoryError {
49	    RepositoryError::Backend(Box::new(std::io::Error::other(msg.to_string())))
50	}
51	
52	/// Builds the insertable `audit_log` row from a domain `AuditEntry`. `determining_policies`
53	/// is always `Some(json)` (never `NULL`, even for an empty vec — simplest of the two
54	/// column-storage options and infallible either way).
55	fn entry_to_model(e: &AuditEntry) -> audit_log::ActiveModel {
56	    audit_log::ActiveModel {
57	        id: Set(e.id),
58	        occurred_at: Set(e.occurred_at),
59	        actor_prn: Set(e.actor_prn.clone()),
60	        action: Set(e.action.clone()),
61	        resource_prn: Set(e.resource_prn.clone()),
62	        outcome: Set(e.outcome.as_str().to_string()),
63	        determining_policies: Set(Some(serde_json::to_string(&e.determining_policies).expect("Vec<String> always serializes"))),
64	        detail: Set(e.detail.to_string()),
65	        correlation_id: Set(e.correlation_id),
66	    }
67	}
68	
69	/// Inverse of [`entry_to_model`]'s `determining_policies` half: `NULL` or an empty string is
70	/// an empty vec; otherwise the stored JSON array is parsed back. Unparseable JSON is a
71	/// `Backend` error — the row was written by this same adapter, so a failure here means the
72	/// data is corrupt.
73	fn policies_from_column(raw: Option<&str>) -> Result<Vec<String>, RepositoryError> {
74	    match raw {
75	        None | Some("") => Ok(Vec::new()),
76	        Some(s) => serde_json::from_str(s).map_err(backend_err),
77	    }
78	}
79	
80	/// Inverse of [`entry_to_model`]'s `detail` half: an empty string falls back to `{}` (mirrors
81	/// the migration test's seed row, m0006); otherwise the stored JSON string is parsed back.
82	/// Unparseable JSON is a `Backend` error, same posture as [`policies_from_column`].
83	fn detail_from_column(raw: &str) -> Result<serde_json::Value, RepositoryError> {
84	    if raw.is_empty() {
85	        return Ok(serde_json::json!({}));
86	    }
87	    serde_json::from_str(raw).map_err(backend_err)
88	}
89	
90	/// Reconstructs the domain `AuditEntry` from a stored row. `outcome` is a plain unconstrained
91	/// TEXT column (m0006 has no CHECK constraint on it) — this parse is the safety net: the
92	/// adapter only ever writes `AuditOutcome::as_str()` values, so a stored `outcome` outside
93	/// `{committed, denied}` would mean external tampering or corruption. Surfaced as `Backend`,
94	/// never a silent default, mirroring `pg_repository.rs::map_principal_row`'s posture for a bad
95	/// enum.
96	fn model_to_entry(m: audit_log::Model) -> Result<AuditEntry, RepositoryError> {
97	    let outcome = AuditOutcome::parse(&m.outcome).ok_or_else(|| backend_err(format!("bad audit outcome: {}", m.outcome)))?;
98	    let determining_policies = policies_from_column(m.determining_policies.as_deref())?;
99	    let detail = detail_from_column(&m.detail)?;
100	    Ok(AuditEntry {
101	        id: m.id,
102	        occurred_at: m.occurred_at,
103	        actor_prn: m.actor_prn,
104	        action: m.action,
105	        resource_prn: m.resource_prn,
106	        outcome,
107	        determining_policies,
108	        detail,
109	        correlation_id: m.correlation_id,
110	    })
111	}
112	
113	/// `iam_audit_records_total` counts non-erroring inserts, not committed rows (spec §5.2): a
114	/// [`record`](AuditLog::record) call on the caller's own in-flight transaction still bumps
115	/// `result="ok"` here even if that transaction is later rolled back — this counter is
116	/// instrumentation for the INSERT itself succeeding, not a durability/visibility promise.
117	fn record_metric(e: &AuditEntry, result: &'static str) {
118	    counter!(names::IAM_AUDIT_RECORDS_TOTAL, "outcome" => e.outcome.as_str(), "result" => result).increment(1);
119	}
120	
121	#[async_trait]
122	impl AuditLog for PgAuditLog {
123	    async fn record_out_of_band(&self, e: &AuditEntry) -> Result<(), RepositoryError> {
124	        match entry_to_model(e).insert(&self.db).await {
125	            Ok(_) => {
126	                record_metric(e, "ok");
127	                Ok(())
128	            }
129	            Err(err) => {
130	                record_metric(e, "error");
131	                Err(map_err(err))
132	            }
133	        }
134	    }
135	
136	    async fn record(&self, tx: &dyn Transaction, e: &AuditEntry) -> Result<(), RepositoryError> {
137	        let txn = recover_txn(tx)?;
138	        match entry_to_model(e).insert(txn).await {
139	            Ok(_) => {
140	                record_metric(e, "ok");
141	                Ok(())
142	            }
143	            Err(err) => {
144	                record_metric(e, "error");
145	                Err(map_err(err))
146	            }
147	        }
148	    }
149	
150	    async fn query(&self, f: &AuditFilter) -> Result<Vec<AuditEntry>, RepositoryError> {
151	        let mut q = audit_log::Entity::find();
152	        if let Some(actor_prn) = &f.actor_prn {
153	            q = q.filter(audit_log::Column::ActorPrn.eq(actor_prn.clone()));
154	        }
155	        if let Some(resource_prn) = &f.resource_prn {
156	            q = q.filter(audit_log::Column::ResourcePrn.eq(resource_prn.clone()));
157	        }
158	        if let Some(action) = &f.action {
159	            q = q.filter(audit_log::Column::Action.eq(action.clone()));
160	        }
161	        if let Some(outcome) = f.outcome {
162	            q = q.filter(audit_log::Column::Outcome.eq(outcome.as_str()));
163	        }
164	        if let Some(from) = f.from {
165	            q = q.filter(audit_log::Column::OccurredAt.gte(from));
166	        }
167	        if let Some(to) = f.to {
168	            q = q.filter(audit_log::Column::OccurredAt.lte(to));
169	        }
170	        // Keyset paging (port doc contract): the next page is every row strictly older
171	        // (lower id) than the last row of the previous page.
172	        if let Some(cursor) = f.cursor {
173	            q = q.filter(audit_log::Column::Id.lt(cursor));
174	        }
175	
176	        let models = q.order_by_desc(audit_log::Column::Id).limit(f.capped_limit()).all(&self.db).await.map_err(map_err)?;
177	        models.into_iter().map(model_to_entry).collect()
178	    }
179	}
