3	//! Schema-level test for m0006 (SMA-446 Task A4): asserts the `audit_log` table + its SeaORM
4	//! entity exist with the expected columns. The `PgAuditLog` port adapter itself is a later
5	//! task (A5) — this only proves the migration + entity line up, via a trivial insert+count
6	//! through the entity (a missing/mistyped column would fail the INSERT/SELECT this issues,
7	//! not just panic on a `.unwrap()` of absent data).
8	//!
9	//! Runs against an ephemeral Postgres in Docker. In CI (`CI` env set) a missing Docker daemon
10	//! is a HARD FAILURE; on a Docker-less laptop the test skips (returns) with a note — same
11	//! gating pattern as `tests/authz_policy_store.rs`/`tests/service_accounts.rs`.
12	
13	mod support;
14	
15	use chrono::Utc;
16	use paigasus_iam::adapters::id::KernelIdGenerator;
17	use paigasus_iam::adapters::persistence::PgAuditLog;
18	use paigasus_iam::adapters::persistence::entities::audit_log;
19	use paigasus_iam_core::{AuditEntry, AuditFilter, AuditLog, AuditOutcome, IdGenerator};
20	use sea_orm::{ActiveModelTrait, EntityTrait, PaginatorTrait, Set};
21	use uuid::Uuid;
