26	
27	    let before = audit_log::Entity::find().count(&db).await.unwrap();
28	    assert_eq!(before, 0, "freshly migrated audit_log must start empty");
29	
30	    let id = KernelIdGenerator.new_audit_id();
31	    audit_log::ActiveModel {
32	        id: Set(id),
33	        occurred_at: Set(Utc::now()),
34	        actor_prn: Set(Some("prn:pgs:iam:::principal/00000000-0000-0000-0000-000000000001".to_string())),
35	        action: Set("CreateOrganization".to_string()),
36	        resource_prn: Set(None),
37	        outcome: Set("committed".to_string()),
38	        determining_policies: Set(None),
39	        detail: Set("{}".to_string()),
40	        correlation_id: Set(None),
41	    }
42	    .insert(&db)
43	    .await
44	    .unwrap();
45	
46	    let after = audit_log::Entity::find().count(&db).await.unwrap();
