50	/// A denial `AuditEntry` for `actor` at `id`, all sharing the same denied `GetProject`
51	/// shape — the only axis under test is `id`/`actor_prn`.
52	fn denial(id: Uuid, actor: &str) -> AuditEntry {
53	    AuditEntry {
54	        id,
55	        occurred_at: Utc::now(),
56	        actor_prn: Some(actor.to_string()),
57	        action: "GetProject".to_string(),
58	        resource_prn: None,
59	        outcome: AuditOutcome::Denied,
60	        determining_policies: vec!["policy-forbid-1".to_string()],
61	        detail: serde_json::json!({"reason": "no matching allow"}),
62	        correlation_id: None,
63	    }
64	}
65	
66	#[tokio::test]
67	async fn record_out_of_band_then_query_filters_and_paginates() {
68	    let Some((_pg, db)) = support::start_migrated_postgres().await else { return };
69	    let sink = PgAuditLog::new(db.clone());
70	
71	    // Ascending `Uuid::from_u128` ids (byte-big-endian, so larger u128 = larger uuid) so
72	    // `ORDER BY id DESC` is deterministic: id=1 and id=2 belong to actor "a", id=3 to "b".
73	    for (id, actor) in [(Uuid::from_u128(1), "a"), (Uuid::from_u128(2), "a"), (Uuid::from_u128(3), "b")] {
74	        sink.record_out_of_band(&denial(id, actor)).await.expect("record_out_of_band must succeed");
75	    }
76	
77	    // Round-trip check on one row: TEXT-column (de)serialization of `determining_policies`/
78	    // `detail` must survive the write+read, not just the filter/outcome fields.
79	    let base_filter = AuditFilter {
80	        actor_prn: Some("a".to_string()),
81	        resource_prn: None,
82	        action: None,
83	        outcome: Some(AuditOutcome::Denied),
84	        from: None,
85	        to: None,
86	        cursor: None,
87	        limit: 10,
88	    };
89	    let rows = sink.query(&base_filter).await.expect("query must succeed");
90	    assert_eq!(rows.len(), 2, "only actor a's 2 denials must match, newest-first");
91	    assert_eq!(rows[0].id, Uuid::from_u128(2), "id DESC: the higher id comes first");
92	    assert_eq!(rows[1].id, Uuid::from_u128(1));
93	    assert_eq!(rows[0].determining_policies, vec!["policy-forbid-1".to_string()]);
94	    assert_eq!(rows[0].detail, serde_json::json!({"reason": "no matching allow"}));
95	    assert_eq!(rows[0].outcome, AuditOutcome::Denied);
96	
97	    // Keyset pagination: limit=1 returns only the newest match; passing that row's id as the
98	    // next `cursor` returns the next-newest, not the same row again.
99	    let page1 = sink.query(&AuditFilter { limit: 1, ..base_filter.clone() }).await.expect("page1 query must succeed");
100	    assert_eq!(page1.len(), 1);
101	    assert_eq!(page1[0].id, Uuid::from_u128(2));
102	
103	    let page2 = sink
104	        .query(&AuditFilter {
105	            limit: 1,
106	            cursor: Some(page1[0].id),
107	            ..base_filter.clone()
108	        })
109	        .await
110	        .expect("page2 query must succeed");
111	    assert_eq!(page2.len(), 1);
112	    assert_eq!(page2[0].id, Uuid::from_u128(1));
113	
114	    // Actor b's denial must never surface under the actor=a filter.
115	    assert!(rows.iter().all(|e| e.actor_prn.as_deref() == Some("a")));
116	}
117	
118	/// `query`'s `from`/`to` `occurred_at` filters (both `gte`/`lte`, i.e. inclusive on both
119	/// ends) must select only the in-range rows, not silently ignore the bounds.
120	#[tokio::test]
121	async fn query_filters_by_occurred_at_from_and_to() {
122	    let Some((_pg, db)) = support::start_migrated_postgres().await else { return };
123	    let sink = PgAuditLog::new(db.clone());
124	
125	    let base = Utc::now();
126	    let t0 = base - chrono::Duration::hours(2); // before the range
127	    let t1 = base - chrono::Duration::hours(1); // range start (`from`)
128	    let t2 = base; // inside the range
129	    let t3 = base + chrono::Duration::hours(1); // range end (`to`)
130	    let t4 = base + chrono::Duration::hours(2); // after the range
131	
132	    for (id, occurred_at) in [
133	        (Uuid::from_u128(200), t0),
134	        (Uuid::from_u128(201), t1),
135	        (Uuid::from_u128(202), t2),
136	        (Uuid::from_u128(203), t3),
137	        (Uuid::from_u128(204), t4),
138	    ] {
139	        let entry = AuditEntry {
140	            occurred_at,
141	            ..denial(id, "range-actor")
142	        };
143	        sink.record_out_of_band(&entry).await.expect("record_out_of_band must succeed");
144	    }
145	
146	    let rows = sink
147	        .query(&AuditFilter {
148	            actor_prn: Some("range-actor".to_string()),
149	            resource_prn: None,
150	            action: None,
151	            outcome: Some(AuditOutcome::Denied),
152	            from: Some(t1),
153	            to: Some(t3),
154	            cursor: None,
155	            limit: 10,
156	        })
157	        .await
158	        .expect("range query must succeed");
159	
160	    let mut ids: Vec<Uuid> = rows.iter().map(|e| e.id).collect();
161	    ids.sort();
162	    assert_eq!(
163	        ids,
164	        vec![Uuid::from_u128(201), Uuid::from_u128(202), Uuid::from_u128(203)],
165	        "only rows with occurred_at in [from, to] must be returned, both bounds inclusive"
166	    );
167	}
