3	//! `OutboxRelay`: the background drain that turns committed `event_outbox` rows into calls on
4	//! an injected [`EventPublisher`] (SMA-446, Slice B Task B8).
5	//!
6	//! **Multi-replica safety is the point.** Each tick runs entirely on one transaction:
7	//! 1. `SELECT * FROM event_outbox WHERE published_at IS NULL AND parked = false ORDER BY id
8	//!    FOR UPDATE SKIP LOCKED LIMIT batch_size` — locks the selected rows for the duration of the
9	//!    transaction, and `SKIP LOCKED` means a row already locked by ANOTHER relay replica's
10	//!    concurrent tick is silently excluded from this one's result set rather than blocking on
11	//!    it. Two replicas' `run` loops therefore never grab the same row.
12	//! 2. Each locked row is handed to `publisher.publish`; the outcome is written back on the SAME
13	//!    transaction (`published_at` on success, `attempts += 1` and — once `attempts` reaches
14	//!    `max_attempts` — `parked = true` on failure).
15	//! 3. `commit` releases the row locks.
16	//!
17	//! Verified against the vendored `sea-orm 1.1.20` (via `sea-query 0.32.7`, its lock-clause
18	//! backend): `QuerySelect::lock_with_behavior(LockType, LockBehavior)` and
19	//! `sea_orm::sea_query::{LockType::Update, LockBehavior::SkipLocked}` exist and map directly to
20	//! `FOR UPDATE SKIP LOCKED` — no raw-`Statement` fallback needed.
21	//!
22	//! [`OutboxRelay::run`] mirrors `PolicySnapshot::spawn_reload`'s shutdown-watch pattern
23	//! (`tokio::select!` racing a poll-interval sleep against a caller-supplied shutdown future) —
24	//! unlike `spawn_reload`, `run` does not `tokio::spawn` itself; the composition root (a later
25	//! task, B9) spawns it exactly like it already spawns the denial-audit drain in `main.rs`.
26	
27	use std::future::Future;
28	use std::sync::Arc;
29	use std::time::Duration;
30	
31	use chrono::Utc;
32	use paigasus_iam_core::{DomainEvent, EventPublisher, EventType};
33	use sea_orm::sea_query::{LockBehavior, LockType};
34	use sea_orm::{ActiveModelTrait, ColumnTrait, DatabaseConnection, DbErr, EntityTrait, IntoActiveModel, QueryFilter, QueryOrder, QuerySelect, Set, TransactionTrait};
35	
36	use crate::adapters::persistence::entities::event_outbox;
37	
38	/// Per-tick telemetry, both logged (`tracing::info!`) and returned so callers/tests can assert
39	/// on it directly instead of scraping log output.
40	#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
41	pub struct TickReport {
42	    /// Rows locked and processed this tick (published + failed, including newly parked).
43	    pub drained: u64,
44	    /// Of `drained`, how many failed to publish (a subset that includes `parked`).
45	    pub failures: u64,
46	    /// Of `failures`, how many hit `max_attempts` and were parked this tick.
47	    pub parked: u64,
48	    /// Age (seconds) of the oldest row in this tick's batch, if the batch was non-empty — a
49	    /// cheap staleness signal (no extra query: derived from the already-fetched rows).
50	    pub oldest_unpublished_age_secs: Option<i64>,
51	}
52	
53	/// Reconstructs a [`DomainEvent`] from a persisted `event_outbox` row for handing to
54	/// [`EventPublisher::publish`]. Returns `Err` (a human-readable reason) for a malformed row — an
55	/// unrecognized `event_type` wire string, an out-of-range `schema_version`, or invalid `payload`
56	/// JSON — which should never happen for a row this relay's own writer (`PgOutbox::enqueue`, B2)
57	/// ever produced, but a defensive check here costs nothing next to a `panic!`/`unwrap()` that
58	/// would wedge the relay on a single corrupted row. The relay treats this exactly like a failed
59	/// `publish` call (counts against `attempts`, eventually parks).
60	fn row_to_domain_event(row: &event_outbox::Model) -> Result<DomainEvent, String> {
61	    let event_type = EventType::parse(&row.event_type).ok_or_else(|| format!("unrecognized event_type wire string {:?}", row.event_type))?;
62	    let schema_version = u16::try_from(row.schema_version).map_err(|_| format!("schema_version {} out of u16 range", row.schema_version))?;
63	    let payload = serde_json::from_str(&row.payload).map_err(|e| format!("invalid payload json: {e}"))?;
64	    Ok(DomainEvent {
65	        id: row.id,
66	        event_type,
67	        schema_version,
68	        aggregate_prn: row.aggregate_prn.clone(),
69	        actor_prn: row.actor_prn.clone(),
70	        occurred_at: row.occurred_at,
71	        payload,
72	        correlation_id: row.correlation_id,
73	    })
74	}
