76	/// The transactional-outbox relay: polls `event_outbox` for unpublished, unparked rows and
77	/// drains them through an injected [`EventPublisher`]. `Clone`: `DatabaseConnection` is an
78	/// `Arc`-backed pool handle (mirrors every other adapter in this crate), so the composition
79	/// root can hold a relay handle inside a `#[derive(Clone)]` service if it ever needs to.
80	#[derive(Clone)]
81	pub struct OutboxRelay {
82	    db: DatabaseConnection,
83	    poll_interval: Duration,
84	    batch_size: u64,
85	    max_attempts: i32,
86	}
87	
88	impl OutboxRelay {
89	    #[must_use]
90	    pub fn new(db: DatabaseConnection, poll_interval: Duration, batch_size: u64, max_attempts: i32) -> Self {
91	        OutboxRelay {
92	            db,
93	            poll_interval,
94	            batch_size,
95	            max_attempts,
96	        }
97	    }
98	
99	    /// Runs exactly one drain tick (the transactional-outbox pattern described in the module
100	    /// docs) and returns its [`TickReport`]. Public (not just used internally by [`Self::run`])
101	    /// so tests can drive individual, deterministic ticks rather than racing the poll loop.
102	    pub async fn tick(&self, publisher: &dyn EventPublisher) -> Result<TickReport, DbErr> {
103	        let txn = self.db.begin().await?;
104	
105	        let rows = event_outbox::Entity::find()
106	            .filter(event_outbox::Column::PublishedAt.is_null())
107	            .filter(event_outbox::Column::Parked.eq(false))
108	            .order_by_asc(event_outbox::Column::Id)
109	            .limit(self.batch_size)
110	            .lock_with_behavior(LockType::Update, LockBehavior::SkipLocked)
111	            .all(&txn)
112	            .await?;
113	
114	        let mut report = TickReport {
115	            drained: rows.len() as u64,
116	            oldest_unpublished_age_secs: rows.first().map(|r| Utc::now().signed_duration_since(r.occurred_at).num_seconds()),
117	            ..TickReport::default()
118	        };
119	
120	        for row in rows {
121	            let outcome = match row_to_domain_event(&row) {
122	                Ok(ev) => publisher.publish(&ev).await.map_err(|e| e.to_string()),
123	                Err(reason) => Err(reason),
124	            };
125	
126	            let mut active = row.clone().into_active_model();
127	            match outcome {
128	                Ok(()) => {
129	                    active.published_at = Set(Some(Utc::now()));
130	                }
131	                Err(reason) => {
132	                    report.failures += 1;
133	                    let attempts = row.attempts + 1;
134	                    active.attempts = Set(attempts);
135	                    if attempts >= self.max_attempts {
136	                        active.parked = Set(true);
137	                        report.parked += 1;
138	                        tracing::error!(id = %row.id, event_type = %row.event_type, attempts, reason = %reason, "outbox event parked after max attempts (poison)");
139	                    } else {
140	                        tracing::warn!(id = %row.id, event_type = %row.event_type, attempts, reason = %reason, "outbox event publish failed; will retry");
141	                    }
142	                }
143	            }
144	            active.update(&txn).await?;
145	        }
146	
147	        txn.commit().await?;
148	
149	        tracing::info!(
150	            drained = report.drained,
151	            failures = report.failures,
152	            parked = report.parked,
153	            oldest_unpublished_age_secs = report.oldest_unpublished_age_secs,
154	            "outbox relay tick"
155	        );
156	
157	        Ok(report)
158	    }
159	
160	    /// Runs the relay loop until `shutdown` resolves: sleep `poll_interval`, tick, repeat —
161	    /// mirrors `PolicySnapshot::spawn_reload`'s `tokio::select!` shutdown-watch exactly (sleep
162	    /// races shutdown first, so the very first tick runs after one poll interval, not
163	    /// immediately). A tick-level error (e.g. a dropped connection) is logged and the loop keeps
164	    /// going; per-row publish failures never reach here — [`Self::tick`] already turns those
165	    /// into `attempts`/`parked` bookkeeping on the same transaction.
166	    pub async fn run<S>(self, publisher: Arc<dyn EventPublisher>, shutdown: S)
167	    where
168	        S: Future<Output = ()> + Send,
169	    {
170	        tokio::pin!(shutdown);
171	        loop {
172	            tokio::select! {
173	                () = tokio::time::sleep(self.poll_interval) => {
174	                    if let Err(err) = self.tick(publisher.as_ref()).await {
175	                        tracing::warn!(error = %err, "outbox relay tick failed; retrying next interval");
176	                    }
177	                }
178	                () = &mut shutdown => break,
179	            }
180	        }
181	    }
182	}
