20	    config.validate().map_err(|e| anyhow::anyhow!(e))?;
21	    paigasus_logging::init("paigasus-iam", &config.log_level);
22	
23	    // A fresh/empty `authz.bootstrap_admins` is valid config (`IamConfig::validate` allows
24	    // it — spec §11), but it means a fresh deployment has no way to grant itself the first
25	    // `platform_admin` role: warn loudly rather than fail boot, since a later `moon`/`psql`
26	    // operator path can still seed one directly. Task 21b wires the actual JIT seed.
27	    if config.authz.bootstrap_admins.is_empty() {
28	        tracing::warn!("no authz.bootstrap_admins configured — a fresh deployment has no platform administrator and cannot create organizations or grant roles");
29	    }
30	
31	    let db = Database::connect(&config.database_url).await?;
32	    Migrator::up(&db, None).await?;
33	    // Built once and cloned into each server task below (a cheap handle-clone: every
34	    // per-aggregate service just wraps the same underlying connection pool, and the wired
35	    // authenticator's JWKS cache/single-flight state is `Arc`-shared) — HTTP and gRPC
36	    // share one `AppState` (Task 16, SMA-442; authn wiring SMA-443). Fails fast when the
37	    // Redis JWKS cache is configured but unreachable; JWKS themselves are fetched lazily
38	    // on first use, so startup stays independent of IdP availability (spec §6.4).
39	    //
40	    // `db` itself (the original handle, not this clone) is kept alive below to build the
41	    // outbox relay (SMA-446 Slice B, Task B9) directly off the same connection pool — the
42	    // relay is wired straight in `main.rs` rather than through `AppState`, so `AppState::new`'s
43	    // signature stays unchanged.
44	    let state = AppState::new(db.clone(), &config).await?;
45	
46	    let request_timeout = Duration::from_secs(30);
